import { NextRequest, NextResponse } from "next/server";
import crypto from "crypto";
import { requireAdmin } from "@/lib/auth/getUser";

export const dynamic = "force-dynamic";

// POST /api/cloudinary-sign
// Admin-only. Returns a signed upload signature so the client can upload
// directly to Cloudinary without exposing the API secret.
export async function POST(req: NextRequest) {
  try {
    // 1. Only admins can get upload signatures
    const { user, response } = await requireAdmin();
    if (response || !user) return response!;

    // 2. Validate env vars
    const apiSecret = process.env.CLOUDINARY_API_SECRET;
    const apiKey = process.env.CLOUDINARY_API_KEY;
    const cloudName = process.env.CLOUDINARY_CLOUD_NAME;

    if (!apiSecret || !apiKey || !cloudName) {
      return NextResponse.json(
        { error: "Cloudinary is not configured on the server." },
        { status: 500 }
      );
    }

    // 3. Build params to sign
    const timestamp = Math.round(Date.now() / 1000);
    const folder = "properties";

    const paramsToSign = `folder=${folder}&timestamp=${timestamp}`;

    // 4. HMAC-SHA1 signature (Cloudinary standard)
    const signature = crypto
      .createHash("sha1")
      .update(paramsToSign + apiSecret)
      .digest("hex");

    return NextResponse.json({
      signature,
      timestamp,
      apiKey,
      cloudName,
      folder,
    });
  } catch (error) {
    console.error("[POST /api/cloudinary-sign]", error);
    return NextResponse.json({ error: "Failed to sign upload" }, { status: 500 });
  }
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { createBrowserClient } from "@supabase/ssr";

const supabase = createBrowserClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);

export default function LoginPage() {
  const router = useRouter();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  async function handleLogin(e: React.FormEvent) {
    e.preventDefault();
    setLoading(true);
    setError("");

    const { error } = await supabase.auth.signInWithPassword({
      email,
      password,
    });

    if (error) {
      setError(error.message);
      setLoading(false);
      return;
    }

    window.location.href = "/admin";
  }

  return (
    <div style={{ display: "flex", height: "100vh", alignItems: "center", justifyContent: "center" }}>
      <form onSubmit={handleLogin} style={{ display: "flex", flexDirection: "column", gap: 12, width: 300 }}>
        <h2>Admin Login</h2>

        {error && <div style={{ color: "red" }}>{error}</div>}

        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />

        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />

        <button type="submit" disabled={loading}>
          {loading ? "Logging in..." : "Login"}
        </button>
      </form>
    </div>
  );
}

import { getProperties } from "@/lib/db/properties";
import PropertyCard from "@/components/listings/PropertyCard";
import Link from "next/link";
