  const sales = allProperties.filter((p) =>
    !p.listingType.toLowerCase().includes("rent")
  );

  return (
    <main className="min-h-screen bg-[#FAFAFA] pt-32 pb-24">
      <div className="max-w-[1440px] mx-auto px-6 lg:px-12">

        {/* Navigation / Back Action */}
