    gsap.registerPlugin(ScrollTrigger);

    if (!textRef.current || !containerRef.current) return;

    // Set the initial hidden state immediately
    gsap.set(textRef.current, {
      y: 120,
      opacity: 0,
      rotationX: -80,
      transformPerspective: 1200,
      transformOrigin: "center bottom",
