          {/* Mobile Menu Toggle */}
          <button
            className="md:hidden text-teal-forest p-2"
            onClick={() => setIsOpen(!isOpen)}
          >
            {isOpen ? <X size={28} /> : <Menu size={28} />}
          </button>
        </div>
      </div>

      {/* Mobile Navigation Overlay */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="absolute top-0 left-0 w-full h-screen bg-white z-[-1] flex flex-col justify-center px-10"
          >
            <div className="space-y-8">
              {navLinks.map((link, i) => (
                <motion.div
                  key={link.name}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: i * 0.1 }}
                >
                  <Link
                    href={link.href}
                    onClick={() => setIsOpen(false)}
                    className="text-4xl font-bold text-teal-forest flex items-center justify-between group"
                  >
                    {link.name}
                    <ChevronRight className="opacity-0 group-hover:opacity-100 transition-opacity" />
                  </Link>
                </motion.div>
              ))}
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 0.5 }}
                className="pt-10"
              >
                <Link
                  href="/#contact"
                  className="block w-full text-center py-5 bg-teal-forest text-white uppercase tracking-widest font-bold"
                >
                  Contact Us
                </Link>
              </motion.div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
}

"use client";

import { useRef } from "react";
import { useImageUpload } from "@/hooks/useImageUpload";

type ImageUploaderProps = {
  value: string[]; // controlled array of URLs
  onChange: (urls: string[]) => void;
};

export default function ImageUploader({ value = [], onChange }: ImageUploaderProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const { uploadImages, uploading } = useImageUpload();

  async function handleUpload(fileList: FileList | null) {
    if (!fileList || fileList.length === 0) return;

    try {
      const newUrls = await uploadImages(fileList);
      onChange([...value, ...newUrls]);
    } catch (error) {
      console.error("Upload error:", error);
      alert("One or more images failed to upload.");
    }
  }

  function removeImage(url: string) {
    // 1. Notify parent immediately (Optimistic UI)
    const next = value.filter((imgUrl) => imgUrl !== url);
    onChange(next);

    // 2. Optional: Extract publicId and cleanup Cloudinary
    const publicId = extractPublicId(url);
    if (publicId && publicId !== url) {
      fetch("/api/cloudinary-delete", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ publicIds: [publicId] }),
      }).catch((err) => console.warn("Background delete failed:", err));
    }
  }

  return (
    <div className="space-y-4">
      {/* ── Drop Zone ───────────────────────────────────────────────────── */}
      <div
        onClick={() => !uploading && inputRef.current?.click()}
        className={`
          relative flex flex-col items-center justify-center gap-3
