          ))}
        </div>
      )}
    </div>
  );
}

function extractPublicId(url: string): string {
  try {
    const parts = url.split("/upload/");
    if (parts.length < 2) return "";
    return parts[1].replace(/^v\d+\//, "").replace(/\.[^/.]+$/, "");
  } catch {
    return "";
  }
}

